PRIOR = [('1.0', '16 June 2025', 'Initial release.', 'Dr Alfred Ang'), ('2.0', '17 August 2026', 'Retitled and rebuilt for autonomous-agent security; five activities added. TSC K/A text unchanged.', 'Dr Alfred Ang'), ('2.1', '18 August 2026', 'Added prompt-injection, PDPA, guardrail, approval, skill/plugin and visual coverage. TSC K/A text unchanged.', 'Dr Alfred Ang'), ('3.0', '20 August 2026', 'Evidence-grounded 207-slide rebuild with product boundaries, cases, controls, activities and source register. TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.0', '25 August 2026', 'Rebuilt as a 1-day course with three LO-aligned topics, eight no-code activities and a reflection-based practical assessment. TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.1', '25 August 2026', 'Refreshed trainer visuals and embedded the YouTube Online Video; scope, timing and TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.2', '25 August 2026', 'Added coding-harness and latest-AI-agents reference slides to the deck (Claude Code, Codex, DeepSeek Harness; OpenClaw, Hermes, Prime Agent, OpenWorker, QM). Schedule and TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.3', '25 August 2026', "Beefed up Topic 3 with Singapore AI case studies (adoption vs cybersecurity, gen-AI brand damage, agentic testing, healthcare AgentSea), a brand-damage discussion/debrief, a 'Key Challenges of AI to Business' capstone and a visual multi-agent map. Schedule and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.4', '25 August 2026', 'Activity 5 rebuilt around the AI Data Policy Generator website (learner-supplied training API key, 7-part IMDA/PDPA-aligned policy framework). Slides, LG and activity pack aligned; added a worked-example slide with concrete Scope, Roles, Rules and Review examples. Schedule timing and TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.5', '25 August 2026', "Added Topic 1 slide 'Probabilistic Output — Why Traditional Security Struggles' contrasting deterministic software with probabilistic LLM output and the challenge to rule-based defences. Schedule timing and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.6', '25 August 2026', "Added Topic 1 slide 'When the Loop Goes Wrong — Misreading the Goal' after the concrete agentic-loop example: an open-ended 'remove the malware at all costs' goal escalates to wiping every file, motivating the Topic 3 guardrails. Schedule timing and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.7', '25 August 2026', "Added Topic 1 slide 'An Agent on WhatsApp Is Exposed to the Internet' after the TIA Support slide: a public messaging agent accepts messages from anyone, so prompt injection and data poisoning can extract confidential data or harm the server. Schedule timing and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.8', '26 August 2026', "Added verified case study 'Case — A Malicious Skill on ClawHub' (Snyk, Feb 2026) at the end of the Topic 1 Skills and Tools section: a fake Google skill whose SKILL.md instructions tricked users into installing malware. Schedule timing and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.9', '26 August 2026', "Activity 3 reworked: the agent now creates a 10-slide 'AI Security for AI Agents' deck (saved to the Downloads folder), then redesigns it from an uploaded image template — replacing the Envato-template animated-deck flow. Schedule timing and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.10', '26 August 2026', 'Activity 2 reworked: learners now upload MOCK-MARKETING-DATA.xlsx to the Hermes + MiniMax agent and prompt it to analyse the data, generate charts and produce a .docx report with insights, analysis and recommendations. Schedule timing and TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.11', '26 August 2026', 'Added four Topic 1 slides on applications of AI agents in cyber security: threat detection (real-time detection, automated vulnerability analysis, malware classification), network and social-engineering security (intrusion detection, attack classification, phishing defence, log anomaly detection), incident response (patch generation, playbooks, root-cause analysis) and Security Operations Centres (threat hunting, predictive analytics, adaptive decision-making). Learner Guide notes renumbered. TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.12', '26 August 2026', "Added Topic 1 slide 'Agent-to-Agent Messaging - A Security Blind Spot' after the multi-agent worked example: bad or malicious output cascades agent-to-agent, and a growing topology multiplies message paths - reducing visibility and making data-flow tracing and attribution harder. Beefed up Topic 3 security content with ten slides woven into the existing sections: multi-layer bias mitigation; the four structural security gaps of agents (multi-step inputs, tool chaining, opaque execution, untrusted entities); direct vs indirect prompt injection; jailbreaking and jailbreak persistence; a new 'Advanced Threats — A Look Ahead' section (data poisoning, backdoor attacks, AI supply-chain risk, agent-to-agent attacks, misalignment / Goodhart's Law); and human-in-the-loop at machine speed. Schedule timing and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.13', '26 August 2026', 'Practical instrument renamed to Case Study across the assessment set, slides, Lesson Plan and Learner Guide. Each Case Study task trimmed to TWO questions: Task 1 keeps the generative-vs-agentic-vs-agent and useful-vs-not-trusted questions; Task 2 keeps the weak-vs-strong prompt and prompt-principles questions; Task 3 keeps the leaky-vs-guarded chatbot and accountability questions. Marks rebalanced (20/24/26, total 70). Schedule timing and TSC K/A text unchanged.', 'Dr Alfred Ang'), ('4.14', '26 August 2026', "Learning Outcomes slide now carries the full accredited LO1-LO3 wording. Activity overview slides for Activities 1, 4, 6, 7 and 8 regenerated with activity-specific step flows and 'You'll produce' lines matching the activity packs and Learner Guide. Thank You slide layout corrected. Activity PDFs re-stamped to the current version. Schedule timing and TSC K/A text unchanged.", 'Dr Alfred Ang'), ('4.15', '26 August 2026', 'Learner Guide and Lesson Plan realigned to the v4.15 deck: Topic 3 job redesign restructured into a narrative sequence (Why Now, The Stakes, Our Operating Model, The Problem, The Solution, The Intervention, The Product, The Worked Example), all slide references renumbered to the 168-slide deck, and Activity 6 extended with the six simulator personas and the Activity 6-Coaching-Sarah worked transcript.', 'Dr Alfred Ang'), ('4.16', '26 August 2026', 'Lesson Plan slide references aligned to the 168-slide v4.14 deck: the deck total corrected from 165 to 168, and a Slides column added to the one-day schedule giving the exact deck range for every session (all 168 slides covered, no gaps or overlaps).', 'Dr Alfred Ang')]
